import { RATES } from "./rates";

export function format(cents: number, currency: string): string {
  return `${((cents / 100) * (RATES[currency] ?? 1)).toFixed(2)} ${currency}`;
}

import { format } from "@fixture/money";
import { rate } from "@fixture/money/rates";
import * as copy from "@money/format";
import { lazy } from "react";
import logo from "./logo.svg";
import type { Line } from "./types";

const Cart = lazy(() => import("./pages/cart"));
export const TITLE = "Shop";

export function App() {
  const l: Line = { cents: 100 };
  return (
    <main>
      <img src={logo} alt={TITLE} />
      {format(l.cents, "EUR")}
      {rate("EUR")}
      {copy.format(1, "CHF")}
      <Cart />
    </main>
  );
}

import { createRoot } from "react-dom/client";
import "./index.css";
import { App } from "./app";

createRoot(document.getElementById("root") as HTMLElement).render(<App />);

export function startTiles(): Worker {
  return new Worker(new URL("./workers/tiles.worker.ts", import.meta.url), { type: "module" });
}

import { missing } from "./nowhere";

export default function Cart() {
  return <p>{missing}</p>;
}

import { RATES } from "@fixture/money/rates";

export function draw(n: number): number {
  return n * (RATES.EUR ?? 1);
}

self.onmessage = (e: MessageEvent<number>) => self.postMessage(draw(e.data));

export const RATES: Record<string, number> = { EUR: 1, CHF: 0.95 };
export function rate(c: string) {
  return RATES[c];
}
